// The creator research engine (R1, D-41). Shared across workspaces: these tables have no workspace_id, and only the platform's own
// code (jobs, cfctl) calls these queries.
// A creator seen again keeps their status; only the words about them are refreshed.
func (q *Queries) UpsertResearchCreator(ctx context.Context, arg UpsertResearchCreatorParams) (ResearchCreator, error) {
	row := q.db.QueryRow(ctx, upsertResearchCreator,
		arg.Platform,
		arg.Handle,
		arg.ProfileUrl,
		arg.WhySimilar,
		arg.Similarity,
	)
	var i ResearchCreator
	err := row.Scan(
		&i.ID,
		&i.Platform,
		&i.Handle,
		&i.ProfileUrl,
		&i.WhySimilar,
		&i.Similarity,
		&i.Status,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertResearchPost = `-- name: UpsertResearchPost :one
INSERT INTO research_posts (platform, url, external_id, creator_id, posted_at, posted_at_source, duration_s)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (platform, external_id) DO UPDATE
SET posted_at = COALESCE(EXCLUDED.posted_at, research_posts.posted_at),
    posted_at_source = CASE WHEN EXCLUDED.posted_at IS NULL THEN research_posts.posted_at_source ELSE EXCLUDED.posted_at_source END,
    duration_s = COALESCE(EXCLUDED.duration_s, research_posts.duration_s)
WHERE research_posts.creator_id = EXCLUDED.creator_id
RETURNING id, platform, url, external_id, creator_id, posted_at, posted_at_source, duration_s, created_at
`

type UpsertResearchPostParams struct {
	Platform       string
	Url            string
	ExternalID     string
	CreatorID      uuid.UUID
	PostedAt       *time.Time
	PostedAtSource *string
	DurationS      *float64
}

func (q *Queries) UpsertResearchPost(ctx context.Context, arg UpsertResearchPostParams) (ResearchPost, error) {
	row := q.db.QueryRow(ctx, upsertResearchPost,
		arg.Platform,
		arg.Url,
		arg.ExternalID,
		arg.CreatorID,
		arg.PostedAt,
		arg.PostedAtSource,
		arg.DurationS,
	)
	var i ResearchPost
	err := row.Scan(
		&i.ID,
		&i.Platform,
		&i.Url,
		&i.ExternalID,
		&i.CreatorID,
		&i.PostedAt,
		&i.PostedAtSource,
		&i.DurationS,
		&i.CreatedAt,
	)
	return i, err
}
